"""Adaptive full Hamiltonian evolution with explicit transfer-work ledger."""
import argparse,json,time
from pathlib import Path
import numpy as np
from fine_material import FineMaterial as Full
from fine_initial import fine_initial
from initial import initial

def components(m,a,x,p,chi,pi):
 mt=abs(a[0])**2;mf=abs(a[1])**2;mass=mt+mf;u=m.enclosed(mt);gd=m.enclosed(mass);W,F,_,_=m.f(u);ff=m.f((u[1:]+u[:-1])/2)[1];xx=2*x/np.pi
 response=sum(m.vol*(W+m.beta*np.sin(2*x)**2/np.pi**2*F))+sum(m.tw*m.f(sum(mt)*m.tt**2)[0]/m.tt**4);grav=-sum(m.vol*(.5*gd*gd+m.gb*gd))-.5*sum(mass)**2/m.R-sum(mass)/np.sqrt(m.R*m.R+m.b*m.b);amp=np.abs(a)/np.sqrt(m.vol)[None,:];density_grad=.5*m.k*np.sum(m.w*np.sum(np.diff(amp,axis=1)**2,axis=0));kin=float(m.kinetic(a));outer=m.r*m.rm>70
 return {'gravitational_energy':float(grav),'response_energy':float(response),'F_pressure_energy':float(1.5*m.K*sum(m.vol*(mf/m.vol)**(5/3))),'binding_energy':float(-m.eps*sum(mt)),'carrier_spatial_energy':float(.5*sum(m.w*(m.ell2*ff+m.vac)*np.diff(xx)**2)),'carrier_volume_energy':float(m.B*(m.vol@np.sin(x)**2)),'alignment_energy':float(m.J*np.real(np.sum(np.conj(a)*m.alignment(a,x,chi)))),'carrier_kinetic_energy':float(.5*sum(p*p/m.Z(a))),'amplitude_gradient_energy':float(density_grad),'material_flow_energy':float(kin-density_grad),'fixed_outer_T_fraction':float(sum(mt[outer])/sum(mass[outer])),'fixed_outer_mass':float(sum(mass[outer]))}

def exterior_F_energy(m,a,j):
 psi=a[1]/np.sqrt(m.vol);mf=abs(a[1])**2
 return float(1.5*m.K*sum(m.vol[j+1:]*(mf[j+1:]/m.vol[j+1:])**(5/3))+.5*m.k*sum(m.w[j+1:]*abs(np.diff(psi)[j+1:])**2)+.25*m.k*m.w[j]*abs(psi[j+1]-psi[j])**2)

def run(config,output):
 m=Full(wave_h_kpc=config.get('wave_h_kpc',2.),wave_R_kpc=config.get('wave_R_kpc',8000.),coupling=config.get('coupling',True),material_h_kpc=config.get('material_h_kpc',.125));case=config['case'];dest=Path(output)
 a,x,chi,pi,meta=fine_initial(m,case,config.get('equilibrium'))
 p=np.zeros(m.n);E0=Eold=m.full_energy(a,x,p,chi,pi);Q0=float(m.wvol@pi+m.g*sum(abs(a[0])**2));M0=float(np.sum(abs(a)**2));wave0=m.diagnostics(a,x,chi,pi)['wave_energy'];init=m.diagnostics(a,x,chi,pi);initcomp=components(m,a,x,p,chi,pi);trace=[];sink=qs=transfer=0.;t=0.;h=config['dt_Myr'];start=time.monotonic();last_rejections=[];reject=accept=0;maxE=maxQ=maxM=maxW=0.;minh=h;status='completed';next_sample=0.;maxroot=maxfp=0.;far_index=int(np.argmin(abs((m.wr[:-1]+m.wr[1:])/2-500/m.rm)));far_flux=far_source_work=far_positive=far_negative=max_far_error=0.
 jF=int(np.argmin(abs((m.r[:-1]+m.r[1:])/2*m.rm-100.)));EF0=exterior_F_energy(m,a,jF);Fflux=Fgrav=Falign=Fmassflux=0.;maxFledger=0.
 previous_charge_error=0.;last_probe=-128;probe_count=0
 if config.get('resume'):
  prev=json.loads(Path(config['resume']).read_text());ss=np.load(Path(config['resume']).with_name('state.npz'));a=ss['a'].copy();x=ss['alpha'].copy();p=ss['carrier_p'].copy();chi=ss['chi'].copy();pi=ss['pi'].copy();Eold=m.full_energy(a,x,p,chi,pi);E0=prev['initial_energy'];Q0=float(m.wvol@pi+m.g*np.sum(abs(a[0])**2));M0=prev['initial']['mass'];wave0=prev['initial']['wave_energy'];init=prev['initial'];initcomp=prev['initial_components'];meta={'continued_from':config['resume'],'original':prev['initial_meta']};previous_charge_error=prev['max_shift_charge_ledger_error']+prev.get('previous_shift_charge_error_bound',0.);trace=list(prev['trace']);sink=prev['escaped_energy'];qs=0.;transfer=prev['net_material_to_wave_work'];t=prev['completed_time_Myr'];accept=prev['accepted_steps'];reject=prev['rejected_steps'];maxE=prev['max_absolute_energy_ledger_error'];maxM=prev['max_mass_error'];maxW=prev['max_field_work_ledger_error'];minh=prev['minimum_step_Myr'];maxroot=prev['max_carrier_root_residual'];maxfp=prev['max_fixed_point_residual'];next_sample=t+.1;far_flux=prev['net_far_flux_energy'];far_source_work=prev['far_source_work'];far_positive=prev['positive_far_flux_energy'];far_negative=prev['negative_far_flux_energy'];max_far_error=prev['max_far_flux_ledger_error'];EF0=prev['F_outlet']['initial_internal_gradient_energy'];Fflux=prev['F_outlet']['integrated_gradient_energy_flux'];Fgrav=prev['F_outlet']['gravity_work'];Falign=prev['F_outlet']['alignment_work'];Fmassflux=prev['F_outlet']['integrated_F_mass_flux'];maxFledger=prev['F_outlet']['max_local_energy_ledger_error'];h=config['dt_Myr'];last_probe=accept-128
 while t<config['duration_Myr']-1e-10:
  if accept-last_probe>=64 and h<config['dt_Myr']/4:
   h=config['dt_Myr'];last_probe=accept;probe_count+=1

  if time.monotonic()-start>config.get('wall_seconds',240):status='wall_limit_partial';break
  h=min(h,config['duration_Myr']-t);dt=h/m.tdyn;an,xn,pn,cn,vin,ds,dq,info=m.full_step(a,x,p,chi,pi,dt);En=m.full_energy(an,xn,pn,cn,vin);defect=En+ds-Eold;tol=max(config.get('energy_roundoff_floor',5e-13),config.get('step_energy_tolerance',1e-9)*h/config['dt_Myr']);trial_cap=float(min(.9997-m.enclosed(abs(an[0])**2)));bad=trial_cap<=0 or info['fixed_point_error']>1e-9 or info['carrier_root_residual']>1e-8 or abs(defect)>tol or not np.isfinite(En)
  if bad:
   last_rejections.append({'time_Myr':t,'h_Myr':h,'energy_defect':float(defect),'energy_tolerance':tol,'trial_cap_slack':trial_cap,**info});last_rejections=last_rejections[-80:];reject+=1;h*=.5
   if h<config.get('minimum_dt_Myr',1e-7):status='physical_cap_limit' if trial_cap<=0 else 'minimum_step_failure';break
   continue
  amid=(a+an)/2;xm=getattr(m,"last_mid_alpha",(x+xn)/2);cm=(chi+cn)/2;vm=(pi+vin)/2;rate=2*m.J/m.sigma*np.imag(np.conj(amid[0])*m.alignment(amid,xm,cm)[0]);work=-m.g*dt*sum(rate*m.chi_m(vm));transfer+=float(work);ff=-m.c**2*m.ww[far_index]*(cm[far_index+1]-cm[far_index])*(vm[far_index+1]+vm[far_index])/2;far_flux+=float(dt*ff);far_positive+=float(dt*max(ff,0));far_negative+=float(dt*min(ff,0));dep=np.bincount(m.ids,weights=(1-m.frac)*rate,minlength=len(vm))+np.bincount(m.ids+1,weights=m.frac*rate,minlength=len(vm));far_source_work+=float(-m.g*dt*(dep[far_index+1:]@vm[far_index+1:]));dF=(an[1]-a[1])/dt;psi=amid[1]/np.sqrt(m.vol);dotpsi=dF/np.sqrt(m.vol);jf=-m.k*m.w[jF]*np.real(.5*(np.conj(dotpsi[jF])+np.conj(dotpsi[jF+1]))*(psi[jF+1]-psi[jF]));Fflux+=float(dt*jf);Fmassflux+=float(dt*m.k/m.sigma*m.w[jF]*np.imag(np.conj(psi[jF])*psi[jF+1]));muG=m.pot(amid,xm,True)[1][1]-2.5*m.K*(abs(amid[1])**2/m.vol)**(2/3);dmF=(abs(an[1])**2-abs(a[1])**2)/dt;Fgrav-=float(dt*sum(muG[jF+1:]*dmF[jF+1:]));Falign-=float(2*dt*m.J*np.real(np.vdot(m.alignment(amid,xm,cm)[1,jF+1:],dF[jF+1:])));maxFledger=max(maxFledger,abs(exterior_F_energy(m,an,jF)-EF0-Fflux-Fgrav-Falign));a,x,p,chi,pi=an,xn,pn,cn,vin;Eold=En;t+=h;sink+=ds;qs+=dq;accept+=1;minh=min(minh,h);maxroot=max(maxroot,info['carrier_root_residual']);maxfp=max(maxfp,info['fixed_point_error'])
  if t>=next_sample or t>=config['duration_Myr']-1e-10:
   d=m.diagnostics(a,x,chi,pi);comp=components(m,a,x,p,chi,pi);far_energy=float(.5*(m.wvol[far_index+1:]@(pi[far_index+1:]**2))+m.c**2*(.5*(m.ww[far_index+1:]@np.diff(chi)[far_index+1:]**2)+.25*m.ww[far_index]*np.diff(chi)[far_index]**2));max_far_error=max(max_far_error,abs(far_energy+sink-far_source_work-far_flux));maxE=max(maxE,abs(En+sink-E0));maxQ=max(maxQ,abs(m.wvol@pi+m.g*sum(abs(a[0])**2)+qs-Q0));maxM=max(maxM,abs(d['mass']-M0));maxW=max(maxW,abs(d['wave_energy']+sink-wave0-transfer));trace.append({'time_Myr':t,'total_energy':En,'escaped_energy':sink,'net_material_to_wave_work':transfer,'far_flux_energy':far_flux,'far_field_energy':far_energy,'far_source_work':far_source_work,**d,**comp});next_sample=t+.1
   if d['cap_slack']<=0:status='physical_cap_failure';break
  if abs(defect)<tol/16 and info['iterations']<15:h=min(config['dt_Myr'],h*1.25)
 final=m.diagnostics(a,x,chi,pi);finalc=components(m,a,x,p,chi,pi);out={'config':config,'material_grid':{'n':m.n,'uniform_out_to_kpc':320.,'h_kpc':m.material_h_kpc,'qualifier':'Outer tail still coarse; no continuum claim after a wave reaches320kpc'},'status':status,'completed_time_Myr':t,'runtime_seconds':time.monotonic()-start,'accepted_steps':accept,'rejected_steps':reject,'minimum_step_Myr':minh,'initial_meta':meta,'initial':init,'initial_components':initcomp,'initial_energy':E0,'final':final,'final_components':finalc,'escaped_energy':sink,'net_material_to_wave_work':transfer,'max_field_work_ledger_error':maxW,'far_radius_kpc':float((m.wr[far_index]+m.wr[far_index+1])/2*m.rm),'net_far_flux_energy':far_flux,'positive_far_flux_energy':far_positive,'negative_far_flux_energy':far_negative,'far_source_work':far_source_work,'max_far_flux_ledger_error':max_far_error,'max_absolute_energy_ledger_error':maxE,'max_shift_charge_ledger_error':maxQ,'max_mass_error':maxM,'max_carrier_root_residual':maxroot,'max_fixed_point_residual':maxfp,'F_outlet':{'radius_kpc':float((m.r[jF]+m.r[jF+1])/2*m.rm),'initial_internal_gradient_energy':EF0,'final_internal_gradient_energy':exterior_F_energy(m,a,jF),'integrated_gradient_energy_flux':Fflux,'gravity_work':Fgrav,'alignment_work':Falign,'integrated_F_mass_flux':Fmassflux,'max_local_energy_ledger_error':maxFledger,'scope':'F internal+gradient energy outside fixed sphere, explicit gravitational and alignment work; not total gravitational escape energy'},'recovery_probes':probe_count,'previous_shift_charge_error_bound':previous_charge_error,'shift_charge_scope':'Current segment plus preceding error bound; energy/work/flux reference cumulative','trace':trace,'last_rejections':last_rejections,'non_claims':['Finite-carrier free density evolution; no drift assigned to escape','Adaptive local energy-defect control is numerical, not a physical loss term','Stiff-mode and spatial convergence remain mandatory','K30 barotropic F state remains a constitutive assumption','No universal galaxy-population or arbitrary initial-data conclusion']};np.savez_compressed(dest.with_name('state.npz'),a=a,alpha=x,carrier_p=p,chi=chi,pi=pi);dest.write_text(json.dumps(out,indent=2)+'\n');print({k:v for k,v in out.items() if k!='trace'},flush=True)

def main(config):
 ap=argparse.ArgumentParser();ap.add_argument('--output',required=True);a=ap.parse_args();run(config,a.output)
